3	declare(strict_types=1);
4	
5	namespace App\Filament\Concerns;
6	
7	use Filament\Actions\Action;
8	use Filament\GlobalSearch\GlobalSearchResult;
9	use Illuminate\Contracts\Support\Htmlable;
10	use Illuminate\Database\Eloquent\Model;
11	use Illuminate\Support\Collection;
12	use Illuminate\Support\HtmlString;
13	
14	/**
15	 * Fa passare la ricerca globale Filament (cmd+K) attraverso Scout invece
16	 * della LIKE di default (`HasGlobalSearch::getGlobalSearchResults()`), così
17	 * il modello di ricerca è lo stesso indipendentemente dal resource
18	 * (roadmap #23) e lo switch futuro `database` -> `meilisearch` non tocca
19	 * codice qui: cambia solo `SCOUT_DRIVER`.
20	 */
21	trait HasScoutGlobalSearch
22	{
23	    /**
24	     * @return Collection<int, GlobalSearchResult>
25	     */
26	    public static function getGlobalSearchResults(string $search): Collection
27	    {
28	        $model = static::getModel();
29	
30	        return $model::search($search)
31	            ->take(static::getGlobalSearchResultsLimit())
32	            ->get()
33	            ->map(function (Model $record) use ($search): ?GlobalSearchResult {
34	                $url = static::getGlobalSearchResultUrl($record);
35	
36	                if (blank($url)) {
37	                    return null;
38	                }
39	
40	                return new GlobalSearchResult(
41	                    title: static::highlightGlobalSearchTitle(static::getGlobalSearchResultTitle($record), $search),
42	                    url: $url,
43	                    details: static::getGlobalSearchResultDetails($record),
44	                    actions: array_map(
45	                        fn (Action $action) => $action->hasRecord() ? $action : $action->record($record),
46	                        static::getGlobalSearchResultActions($record),
47	                    ),
48	                );
49	            })
50	            ->filter()
51	            ->values();
52	    }
53	
54	    /**
55	     * Evidenzia il termine cercato nel titolo (es. `<mark>`), a prescindere
56	     * dal driver Scout attivo: il driver `database` non fornisce highlighting
57	     * nativo (a differenza di Meilisearch, che lo calcola sul suo indice), e
58	     * il testo effettivamente confrontato in query (`name_search`, JSON
59	     * grezzo cast a testo) non coincide col titolo mostrato (nome nella
60	     * lingua corrente), quindi neanche passando a Meilisearch il suo
61	     * `_formatted` sarebbe direttamente utilizzabile qui. Se il termine non
62	     * compare nel titolo (match avvenuto su slug o altra lingua) resta
63	     * semplicemente non evidenziato, nessun errore.
64	     */
65	    protected static function highlightGlobalSearchTitle(string | Htmlable $title, string $search): string | Htmlable
66	    {
67	        if ($title instanceof Htmlable || blank($search)) {
68	            return $title;
69	        }
70	
71	        $highlighted = preg_replace(
72	            '/' . preg_quote($search, '/') . '/ui',
73	            '<mark>$0</mark>',
74	            e($title),
75	        );
76	
77	        return new HtmlString($highlighted ?? e($title));
78	    }
79	}
