3	namespace AtrioTeam\DigitalHub\Pim\Filament\Tables;
4	
5	use Filament\Actions\ActionGroup;
6	use Filament\Actions\BulkActionGroup;
7	use Filament\Actions\DeleteAction;
8	use Filament\Actions\DeleteBulkAction;
9	use Filament\Actions\EditAction;
10	use Filament\Actions\ViewAction;
11	use Filament\Support\Enums\Width;
12	use Filament\Tables\Columns\Column;
13	use Filament\Tables\Columns\TextColumn;
14	use Filament\Tables\Table;
15	use Illuminate\Database\Eloquent\Model;
16	
17	class DigitalHubTableMacro
18	{
19	    public static function register(): void
20	    {
21	        // register a macro to perform some customization on all tables of the Digital Hub, like adding a default record action to open the edit page
22	        Table::macro('digitalHubTable', function (array $recordActions = []): Table {
23	            // $this is bound to the Table instance at runtime by Laravel's Macroable;
24	            // PHPStan cannot infer this statically for a macro closure.
25	            /** @var Table $this */
26	            // @phpstan-ignore-next-line varTag.variableNotFound, variable.undefined, argument.type
27	            return DigitalHubTableMacro::apply($this, $recordActions);
28	        });
29	    }
30	
31	    /**
32	     * Apply the Digital Hub customizations to a table.
33	     *
34	     * @param array<\Filament\Actions\Action> $recordActions Azioni di riga extra,
35	     *                                                       anteposte all'ActionGroup standard (es. ManageAssetsAction).
36	     */
37	    public static function apply(Table $table, array $recordActions = []): Table
38	    {
39	        $table->recordActions([
40	            ...$recordActions,
41	            ActionGroup::make([
42	                ViewAction::make()
43	                    ->slideOver()
44	                    ->modalWidth(Width::ScreenTwoExtraLarge)
45	                    // pulsante "Modifica" nel footer della modale view → apre la
46	                    // modale edit per lo stesso record, azione nidificata
47	                    // indipendente (non sostituisce la view, si impila sopra).
48	                    // Nome di default 'edit' invariato: eredita la stessa
49	                    // autorizzazione automatica (Resource::canEdit()) della riga.
50	                    ->extraModalFooterActions(fn (ViewAction $action): array => [
51	                        EditAction::make()
52	                            ->slideOver()
53	                            ->modalWidth(Width::ScreenTwoExtraLarge)
54	                            ->record($action->getRecord()),
55	                    ]),
56	                EditAction::make()->slideOver()->modalWidth(Width::ScreenTwoExtraLarge),
57	                DeleteAction::make(),
58	            ]),
59	        ])
60	        ->toolbarActions([
61	            BulkActionGroup::make([
62	                DeleteBulkAction::make()
63	                    ->modalHeading(__('digital-hub::common.delete_confirmation')),
64	            ]),
65	        ])
66	        ->defaultSort('sort')
67	        ->reorderable('sort')
68	        // evidenzia la riga il cui action modal (edit/view) è aperto via URL
69	        // (?tableAction=…&tableActionRecord=…, Livewire #[Url]): copre sia il
70	        // click da un risultato di ricerca globale (roadmap #23) sia il refresh
71	        // di una pagina con un'azione già aperta.
72	        ->recordClasses(function (Model $record): ?string {
73	            $highlightedKey = request()->query('tableActionRecord');
74	            $recordKey = $record->getKey();
75	
76	            if (! is_string($highlightedKey) || ! is_scalar($recordKey)) {
77	                return null;
78	            }
79	
80	            return ((string) $recordKey === $highlightedKey)
81	                ? '!bg-warning-50 dark:!bg-warning-400/10'
82	                : null;
83	        })
84	        ;
85	
86	        // customize filters
87	        $filters = $table->getFilters();
88	        if (count($filters) > 2) {
89	            $table->filtersFormColumns(3);
90	        }
91	
92	        // $table->filters($filters,);
93	
94	
95	        // convert the created_at column to proper timezone and format if it exists
96	        collect($table->getColumns())->each(function (Column $column): void {
97	            if ($column instanceof TextColumn && $column->getName() === 'created_at') {
98	                $column->dateTime('d/m/Y H:i', 'Europe/Rome')->sortable()->toggleable(isToggledHiddenByDefault: true);
99	            }
100	        });
101	
102	        return $table;
103	    }
104	}
