20	use Override;
21	
22	class MaterialResource extends Resource
23	{
24	    use HasScoutGlobalSearch;
25	
26	    protected static ?string $model = Material::class;
27	
28	    protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedSwatch;
29	
30	    protected static ?string $recordTitleAttribute = 'name';
31	
32	    // risorsa nidificata sotto MaterialCategory: non compare in navigazione, si
33	    // raggiunge entrando in una categoria. Il material_category_id è valorizzato
34	    // dalla relazione parent.
35	    public static function getParentResourceRegistration(): ?ParentResourceRegistration
36	    {
37	        return MaterialCategoryResource::asParent()
38	            ->relationship('materials')
39	            ->inverseRelationship('category');
40	    }
41	
42	    // Filament non risolve l'URL di ricerca globale per le risorse nidificate
43	    // (nessuna pagina view/edit dedicata): apre l'indice materiali della
44	    // categoria del record con `tableActionRecord` già valorizzato (la riga
45	    // viene evidenziata da DigitalHubTableMacro). `tableAction=view`
46	    // coerente col resto del pannello (nessuna ViewAction registrata sulle
47	    // tabelle: non apre modali, serve solo a marcare l'intento nell'URL).
48	    // Stessa gate di autorizzazione del default Filament (canView). Nome
49	    // pagina 'index' esplicito: `getUrl()` senza nome passa da
50	    // `getIndexUrl()`, che delega al genitore controllando `hasPage()`
51	    // sulle *sue* pagine — che non includono mai quelle nidificate del
52	    // figlio, quindi perderebbe sempre il parametro `category`.
53	    #[Override]
54	    public static function getGlobalSearchResultUrl(Model $record): ?string
55	    {
56	        if (! ($record instanceof Material) || ! static::canView($record)) {
57	            return null;
58	        }
59	
60	        return static::getUrl('index', [
61	            'category' => $record->category,
62	            'tableAction' => 'view',
63	            'tableActionRecord' => $record,
64	        ]);
65	    }
66	
67	    #[Override]
68	    public static function getModelLabel(): string
69	    {
70	        return __('material.model');
71	    }
72	
73	    #[Override]
74	    public static function getPluralModelLabel(): string
75	    {
76	        return __('material.model_plural');
77	    }
78	
79	    public static function form(Schema $schema): Schema
80	    {
81	        return MaterialForm::configure($schema);
82	    }
83	
84	    public static function table(Table $table): Table
85	    {
86	        return MaterialsTable::configure($table);
87	    }
88	
89	    public static function getRelations(): array
90	    {
91	        return [];
92	    }
93	
94	    public static function getPages(): array
95	    {
96	        return [
97	            'index' => ListMaterials::route('/'),
98	        ];
99	    }
100	}
