5	namespace App\Filament\Resources\Fabrics;
6	
7	use App\Filament\Concerns\HasScoutGlobalSearch;
8	use App\Filament\Resources\FabricCategories\FabricCategoryResource;
9	use App\Filament\Resources\Fabrics\Pages\ListFabrics;
10	use App\Filament\Resources\Fabrics\Schemas\FabricForm;
11	use App\Filament\Resources\Fabrics\Tables\FabricsTable;
12	use App\Models\Fabric;
13	use BackedEnum;
14	use Filament\Resources\ParentResourceRegistration;
15	use Filament\Resources\Resource;
16	use Filament\Schemas\Schema;
17	use Filament\Support\Icons\Heroicon;
18	use Filament\Tables\Table;
19	use Illuminate\Database\Eloquent\Model;
20	use Override;
21	
22	class FabricResource extends Resource
23	{
24	    use HasScoutGlobalSearch;
25	
26	    protected static ?string $model = Fabric::class;
27	
28	    protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedSwatch;
29	
30	    protected static ?string $recordTitleAttribute = 'name';
31	
32	    // risorsa nidificata sotto FabricCategory: non compare in navigazione, si
33	    // raggiunge entrando in una categoria. Il fabric_category_id è valorizzato
34	    // dalla relazione parent.
35	    public static function getParentResourceRegistration(): ?ParentResourceRegistration
36	    {
37	        return FabricCategoryResource::asParent()
38	            ->relationship('fabrics')
39	            ->inverseRelationship('category');
40	    }
41	
42	    // vedi MaterialResource::getGlobalSearchResultUrl(): stesso limite
43	    // Filament sulle risorse nidificate, stessa fix (nome pagina 'index'
44	    // esplicito, altrimenti `getIndexUrl()` perde il parametro `category`)
45	    // e stessa scelta `tableAction=view` (nessuna ViewAction registrata:
46	    // non apre modali, solo l'URL/highlighting sono coerenti col resto).
47	    #[Override]
48	    public static function getGlobalSearchResultUrl(Model $record): ?string
49	    {
50	        if (! ($record instanceof Fabric) || ! static::canView($record)) {
51	            return null;
52	        }
53	
54	        return static::getUrl('index', [
55	            'category' => $record->category,
56	            'tableAction' => 'view',
57	            'tableActionRecord' => $record,
58	        ]);
59	    }
60	
61	    #[Override]
62	    public static function getModelLabel(): string
63	    {
64	        return __('fabric.model');
65	    }
66	
67	    #[Override]
68	    public static function getPluralModelLabel(): string
69	    {
70	        return __('fabric.model_plural');
71	    }
72	
73	    public static function form(Schema $schema): Schema
74	    {
75	        return FabricForm::configure($schema);
76	    }
77	
78	    public static function table(Table $table): Table
79	    {
80	        return FabricsTable::configure($table);
81	    }
82	
83	    public static function getRelations(): array
84	    {
85	        return [];
86	    }
87	
88	    public static function getPages(): array
89	    {
90	        return [
91	            'index' => ListFabrics::route('/'),
92	        ];
93	    }
94	}
