3	declare(strict_types=1);
4	
5	namespace Tests\Feature\Search;
6	
7	use App\Filament\Resources\FabricCategories\FabricCategoryResource;
8	use App\Filament\Resources\Fabrics\FabricResource;
9	use App\Filament\Resources\MaterialCategories\MaterialCategoryResource;
10	use App\Filament\Resources\Materials\MaterialResource;
11	use App\Filament\Resources\Products\ProductResource;
12	use App\Models\Category1;
13	use App\Models\Category2;
14	use App\Models\Fabric;
15	use App\Models\FabricCategory;
16	use App\Models\Material;
17	use App\Models\MaterialCategory;
18	use App\Models\Product;
19	use App\Models\ProductType;
20	use App\Models\User;
21	use Filament\Facades\Filament;
22	use Illuminate\Foundation\Testing\RefreshDatabase;
23	use Tests\TestCase;
24	
25	/**
26	 * Ricerca globale cross-collection (roadmap #23): i resource Filament
27	 * passano da Scout (driver "database" in test/dev) invece della LIKE di
28	 * default, così lo switch a Meilisearch non richiede di riscrivere questi
29	 * resource — vedi App\Filament\Concerns\HasScoutGlobalSearch.
30	 */
31	class GlobalSearchTest extends TestCase
32	{
33	    use RefreshDatabase;
34	
35	    protected function setUp(): void
36	    {
37	        parent::setUp();
38	
39	        // getGlobalSearchResultUrl() gate su canView/canEdit: serve un utente
40	        // autenticato, altrimenti Filament nega di default (nessuna policy).
41	        $this->actingAs(User::factory()->superAdmin()->create());
42	        Filament::setCurrentPanel('admin');
43	    }
44	
45	    public function test_product_resource_finds_records_via_scout(): void
46	    {
47	        $category1 = Category1::create(['name' => ['it' => 'Indoor']]);
48	        $category2 = Category2::create(['name' => ['it' => 'Collezione'], 'category_1_id' => $category1->id]);
49	        $productType = ProductType::create([
50	            'name' => ['it' => 'Tavolo'],
51	            'attribute_schema_class' => \App\Pim\Schemas\ProductAttributes::class,
52	        ]);
53	
54	        $product = Product::create([
55	            'name' => ['it' => 'Tavolino Kandy'],
56	            'category_2_id' => $category2->id,
57	            'product_type_id' => $productType->id,
58	        ]);
59	        Product::create([
60	            'name' => ['it' => 'Divano Modulare'],
61	            'category_2_id' => $category2->id,
62	            'product_type_id' => $productType->id,
63	        ]);
64	
65	        $results = ProductResource::getGlobalSearchResults('Kandy');
66	
67	        $this->assertCount(1, $results);
68	        $this->assertSame(ProductResource::getGlobalSearchResultUrl($product), $results->first()->url);
69	    }
70	
71	    public function test_material_resource_finds_records_via_scout_and_builds_nested_url(): void
72	    {
73	        $category = MaterialCategory::create(['name' => ['it' => 'Legni']]);
74	        $material = Material::create(['name' => ['it' => 'Ebano lucido'], 'material_category_id' => $category->id]);
75	        Material::create(['name' => ['it' => 'Vetro'], 'material_category_id' => $category->id]);
76	
77	        $results = MaterialResource::getGlobalSearchResults('Ebano');
78	
79	        $this->assertCount(1, $results);
80	        $this->assertSame(
81	            route('filament.admin.resources.material-categories.materials.index', [
82	                'category' => $category->getKey(),
83	                'tableAction' => 'view',
84	                'tableActionRecord' => $material->getKey(),
85	            ]),
86	            $results->first()->url,
87	        );
88	    }
89	
90	    public function test_fabric_resource_finds_records_via_scout_and_builds_nested_url(): void
91	    {
92	        $category = FabricCategory::create(['name' => ['it' => 'Cotoni']]);
93	        $fabric = Fabric::create(['name' => ['it' => 'Lino grezzo'], 'fabric_category_id' => $category->id]);
94	        Fabric::create(['name' => ['it' => 'Velluto blu'], 'fabric_category_id' => $category->id]);
95	
96	        $results = FabricResource::getGlobalSearchResults('Lino');
97	
98	        $this->assertCount(1, $results);
99	        $this->assertSame(
100	            route('filament.admin.resources.fabric-categories.fabrics.index', [
101	                'category' => $category->getKey(),
102	                'tableAction' => 'view',
103	                'tableActionRecord' => $fabric->getKey(),
104	            ]),
105	            $results->first()->url,
106	        );
107	    }
108	
109	    public function test_search_is_scoped_to_the_query(): void
110	    {
111	        $category = MaterialCategory::create(['name' => ['it' => 'Legni']]);
112	        Material::create(['name' => ['it' => 'Ebano lucido'], 'material_category_id' => $category->id]);
113	
114	        $results = MaterialResource::getGlobalSearchResults('nessuna corrispondenza');
115	
116	        $this->assertCount(0, $results);
117	    }
118	
119	    /**
120	     * `name` è JSON (translatable): MySQL confronta il JSON grezzo con LIKE
121	     * usando collation binaria (case-sensitive) a prescindere dalla collation
122	     * di connessione. La colonna generata `name_search` (cast a testo, vedi
123	     * migrazione `add_name_search_columns_for_scout`) aggira il problema.
124	     */
125	    public function test_search_is_case_insensitive(): void
126	    {
127	        $category = MaterialCategory::create(['name' => ['it' => 'Legni']]);
128	        Material::create(['name' => ['it' => 'Ebano Lucido'], 'material_category_id' => $category->id]);
129	
130	        $this->assertCount(1, MaterialResource::getGlobalSearchResults('ebano lucido'));
131	        $this->assertCount(1, MaterialResource::getGlobalSearchResults('EBANO LUCIDO'));
132	        $this->assertCount(1, MaterialResource::getGlobalSearchResults('eBaNo'));
133	    }
134	
135	    /**
136	     * Le tassonomie (FabricCategory, MaterialCategory, …) sono indicizzate
137	     * a sé: il nome di un singolo tessuto/materiale (es. "WHITE ROS 101")
138	     * non contiene il nome della sua categoria (es. "Velluto"), quindi
139	     * senza indicizzare anche la categoria la ricerca di "velluto" non
140	     * trovava nulla.
141	     */
142	    public function test_taxonomy_categories_are_globally_searchable(): void
143	    {
144	        FabricCategory::create(['name' => ['it' => 'Velluto']]);
145	        FabricCategory::create(['name' => ['it' => 'Velluto trapuntato']]);
146	        FabricCategory::create(['name' => ['it' => 'Boucle']]);
147	
148	        $this->assertCount(2, FabricCategoryResource::getGlobalSearchResults('velluto'));
149	    }
150	
151	    public function test_material_category_is_globally_searchable(): void
152	    {
153	        MaterialCategory::create(['name' => ['it' => 'Legni pregiati']]);
154	        MaterialCategory::create(['name' => ['it' => 'Metalli']]);
155	
156	        $this->assertCount(1, MaterialCategoryResource::getGlobalSearchResults('legni'));
157	    }
158	
159	    /**
160	     * Highlighting calcolato lato applicazione (non dal motore di ricerca):
161	     * funziona identico coi driver Scout "database" e "meilisearch" e non
162	     * dipende da `_formatted`, che comunque non sarebbe direttamente
163	     * utilizzabile qui (il testo indicizzato è `name_search`, JSON grezzo,
164	     * diverso dal titolo mostrato — nome nella lingua corrente).
165	     */
166	    public function test_search_result_title_highlights_the_matched_term(): void
167	    {
168	        FabricCategory::create(['name' => ['it' => 'Velluto trapuntato']]);
169	
170	        $title = (string) FabricCategoryResource::getGlobalSearchResults('velluto')->first()->title;
171	
172	        $this->assertSame('<mark>Velluto</mark> trapuntato', $title);
173	    }
174	
175	    public function test_search_result_title_is_not_highlighted_when_the_term_is_not_in_the_title(): void
176	    {
177	        // match sullo slug, non sul nome mostrato: nessun highlighting, nessun errore.
178	        $category = FabricCategory::create(['name' => ['it' => 'Boucle'], 'slug' => 'boucle-speciale']);
179	
180	        $title = (string) FabricCategoryResource::getGlobalSearchResults('speciale')->first()->title;
181	
182	        $this->assertSame($category->name, $title);
183	    }
184	}
