 * di ricerca apre l'indice con l'azione di riga già aperta via URL
 * (`?tableAction=…&tableActionRecord=…`, Livewire #[Url]). I resource
 * nidificati (Material, Fabric) sovrascrivono questo metodo per aggiungere
 * il parametro del genitore, riusando `getGlobalSearchTableActionParameters()`.
 */
public static function getGlobalSearchResultUrl(Model $record): ?string
{
    $parameters = static::getGlobalSearchTableActionParameters($record);

    if ($parameters === null) {
        return null;
    }

    return static::getUrl('index', $parameters);
}

/**
