 * editarlo, altrimenti `view` (la ViewAction è nascosta a chi può editare,
 * vedi DigitalHubTableMacro). `null` se non può fare né l'una né l'altra
 * cosa: il risultato viene scartato dalla ricerca.
 *
 * @return array<string, mixed>|null
 */
protected static function getGlobalSearchTableActionParameters(Model $record): ?array
{
    $tableAction = match (true) {
        static::canEdit($record) => 'edit',
        static::canView($record) => 'view',
        default => null,
    };

    if ($tableAction === null) {
        return null;
    }

    return [
        'tableAction' => $tableAction,
        'tableActionRecord' => $record,
    ];
}

