3	declare(strict_types=1);
4	
5	namespace Tests\Feature\Products;
6	
7	use App\Filament\Resources\Products\Pages\ListProducts;
8	use App\Models\Category1;
9	use App\Models\Category2;
10	use App\Models\Material;
11	use App\Models\MaterialCategory;
12	use App\Models\Product;
13	use App\Models\ProductType;
14	use App\Models\User;
15	use AtrioTeam\DigitalHub\Pim\Filament\Tables\DigitalHubTableMacro;
16	use Filament\Facades\Filament;
17	use Illuminate\Foundation\Testing\RefreshDatabase;
18	use Livewire\Livewire;
19	use Tests\TestCase;
20	
21	/**
22	 * `ViewAction` (roadmap #23, tableAction=view sui risultati di ricerca
23	 * globale) riusa lo stesso ProductForm di EditAction ma read-only: il form
24	 * più a rischio del pannello (NestedCheckboxSelect, AttributesEditorSection
25	 * reattiva — quest'ultima nota per un TypeError al re-render su EditAction,
26	 * vedi ProductMaterialsNestedSelectTest). Verifica che il montaggio della
27	 * modale "view" non sollevi errori e mostri lo stato corretto.
28	 */
29	class ProductViewActionTest extends TestCase
30	{
31	    use RefreshDatabase;
32	
33	    protected function setUp(): void
34	    {
35	        parent::setUp();
36	
37	        DigitalHubTableMacro::register();
38	    }
39	
40	    public function test_view_action_mounts_and_shows_the_record_state(): void
41	    {
42	        $this->actingAs(User::factory()->superAdmin()->create());
43	        Filament::setCurrentPanel('admin');
44	
45	        $category1 = Category1::create(['name' => ['it' => 'Indoor']]);
46	        $category2 = Category2::create(['name' => ['it' => 'Collezione'], 'category_1_id' => $category1->id]);
47	        $productType = ProductType::create([
48	            'name' => ['it' => 'Divano'],
49	            'attribute_schema_class' => \App\Pim\Schemas\ProductAttributes::class,
50	        ]);
51	
52	        $materialCategory = MaterialCategory::create(['name' => ['it' => 'Legni']]);
53	        $oak = Material::create(['name' => ['it' => 'Rovere'], 'material_category_id' => $materialCategory->id]);
54	
55	        $product = Product::create([
56	            'name' => ['it' => 'Prodotto vista'],
57	            'category_2_id' => $category2->id,
58	            'product_type_id' => $productType->id,
59	            'properties' => ['sku' => 'SKU-VIEW'],
60	        ]);
61	        $product->materials()->attach($oak->id);
62	
63	        // 'name' non è verificabile qui: è translatable, quindi wrappato in
64	        // TranslationSection (Tabs) sotto 'name.it'/'name.en', non incluso
65	        // flat da getFlatComponents() con la chiave 'name' — comportamento
66	        // identico su EditAction, non specifico di ViewAction (verificato).
67	        Livewire::test(ListProducts::class)
68	            ->mountTableAction('view', $product)
69	            ->assertSchemaStateSet(['materials' => [(string) $oak->id]]);
70	    }
71	
72	    /**
73	     * NestedCheckboxSelect è un campo completamente custom (Alpine/Blade,
74	     * niente componenti Filament nativi sotto): non rispettava affatto lo
75	     * stato disabled di Filament, restando cliccabile anche in ViewAction —
76	     * bug scoperto in verifica manuale. Fix nella view Blade
77	     * (`nested-checkbox-select.blade.php`): legge `$isDisabled()` e blocca
78	     * sia gli input (attributo `disabled`) sia `toggleCategory()` lato Alpine.
79	     */
80	    public function test_nested_checkbox_select_is_disabled_on_view_but_not_on_edit(): void
81	    {
82	        $this->actingAs(User::factory()->superAdmin()->create());
83	        Filament::setCurrentPanel('admin');
84	
85	        $category1 = Category1::create(['name' => ['it' => 'Indoor']]);
86	        $category2 = Category2::create(['name' => ['it' => 'Collezione'], 'category_1_id' => $category1->id]);
87	        $productType = ProductType::create([
88	            'name' => ['it' => 'Divano'],
89	            'attribute_schema_class' => \App\Pim\Schemas\ProductAttributes::class,
90	        ]);
91	        $materialCategory = MaterialCategory::create(['name' => ['it' => 'Legni']]);
92	        $oak = Material::create(['name' => ['it' => 'Rovere'], 'material_category_id' => $materialCategory->id]);
93	        $product = Product::create([
94	            'name' => ['it' => 'Prodotto vista'],
95	            'category_2_id' => $category2->id,
96	            'product_type_id' => $productType->id,
97	        ]);
98	        $product->materials()->attach($oak->id);
99	
100	        foreach (['view' => true, 'edit' => false] as $action => $expectedDisabled) {
101	            $schema = Livewire::test(ListProducts::class)
102	                ->mountTableAction($action, $product)
103	                ->instance()
104	                ->getSchema('mountedActionSchema0');
105	
106	            $field = $schema->getFlatComponents(withActions: false, withHidden: true)['materials'];
107	
108	            $this->assertSame($expectedDisabled, $field->isDisabled(), "azione [{$action}]");
109	        }
110	    }
111	
112	    /**
113	     * Pulsante "Modifica" nel footer della modale view (`extraModalFooterActions`
114	     * su `ViewAction`, `DigitalHubTableMacro::apply()`): azione nidificata
115	     * indipendente che apre la modale edit sullo stesso record, impilata
116	     * sopra la view (non la sostituisce). Nome di default 'edit' invariato:
117	     * eredita la stessa autorizzazione automatica della riga, nessun codice
118	     * di autorizzazione duplicato qui.
119	     */
120	    public function test_view_modal_footer_edit_action_opens_a_nested_editable_modal_for_the_same_record(): void
121	    {
122	        $this->actingAs(User::factory()->superAdmin()->create());
123	        Filament::setCurrentPanel('admin');
124	
125	        $category1 = Category1::create(['name' => ['it' => 'Indoor']]);
126	        $category2 = Category2::create(['name' => ['it' => 'Collezione'], 'category_1_id' => $category1->id]);
127	        $productType = ProductType::create([
128	            'name' => ['it' => 'Divano'],
129	            'attribute_schema_class' => \App\Pim\Schemas\ProductAttributes::class,
130	        ]);
131	        $materialCategory = MaterialCategory::create(['name' => ['it' => 'Legni']]);
132	        $oak = Material::create(['name' => ['it' => 'Rovere'], 'material_category_id' => $materialCategory->id]);
133	        $product = Product::create([
134	            'name' => ['it' => 'Prodotto vista'],
135	            'category_2_id' => $category2->id,
136	            'product_type_id' => $productType->id,
137	        ]);
138	        $product->materials()->attach($oak->id);
139	
140	        $instance = Livewire::test(ListProducts::class)
141	            ->mountTableAction(['view', 'edit'], $product)
142	            ->instance();
143	
144	        $this->assertCount(2, $instance->mountedActions);
145	        $this->assertSame('view', $instance->mountedActions[0]['name']);
146	        $this->assertSame('edit', $instance->mountedActions[1]['name']);
147	
148	        $nestedField = $instance->getSchema('mountedActionSchema1')
149	            ->getFlatComponents(withActions: false, withHidden: true)['materials'];
150	
151	        $this->assertSame([(string) $oak->id], $nestedField->getState());
152	        $this->assertFalse($nestedField->isDisabled());
153	    }
154	}
