20	 * Atterrando su una tabella da un risultato di ricerca globale (roadmap
21	 * #23) l'URL contiene `?tableAction=edit&tableActionRecord=<id>` (Livewire
22	 * `#[Url]`, apre anche l'action modal). La riga corrispondente riceve uno
23	 * sfondo evidenziato — `DigitalHubTableMacro::apply()` — per essere
24	 * individuata visivamente nell'elenco, non solo nella modale.
25	 */
26	class SearchResultRowHighlightTest extends TestCase
27	{
28	    use RefreshDatabase;
29	
30	    protected function setUp(): void
31	    {
32	        parent::setUp();
33	
34	        // registrato normalmente dal boot del DigitalHubPlugin, che nei test
35	        // Livewire non viene eseguito
36	        DigitalHubTableMacro::register();
37	    }
38	
39	    public function test_the_record_matching_the_url_query_string_is_highlighted(): void
40	    {
41	        $this->actingAs(User::factory()->superAdmin()->create());
42	        Filament::setCurrentPanel('admin');
43	
44	        $category1 = Category1::create(['name' => ['it' => 'Indoor']]);
45	        $category2 = Category2::create(['name' => ['it' => 'Collezione'], 'category_1_id' => $category1->id]);
46	        $productType = ProductType::create([
47	            'name' => ['it' => 'Tavolo'],
48	            'attribute_schema_class' => \App\Pim\Schemas\ProductAttributes::class,
49	        ]);
50	
51	        $highlighted = Product::create(['name' => ['it' => 'Tavolino Kandy'], 'category_2_id' => $category2->id, 'product_type_id' => $productType->id]);
52	        $other = Product::create(['name' => ['it' => 'Divano Modulare'], 'category_2_id' => $category2->id, 'product_type_id' => $productType->id]);
53	
54	        // Livewire::test() non simula una vera richiesta HTTP: request() dentro
55	        // al ciclo di vita del componente (mount/booted) non vede query string
56	        // impostate manualmente prima o dopo la chiamata. withQueryParams() è
57	        // l'unico modo per farla arrivare davvero dentro il componente.
58	        $table = Livewire::withQueryParams(['tableActionRecord' => (string) $highlighted->getKey()])
59	            ->test(ListProducts::class)
60	            ->instance()
61	            ->getTable();
62	
63	        $this->assertContains('!bg-warning-50 dark:!bg-warning-400/10', $table->getRecordClasses($highlighted));
64	        $this->assertSame([], $table->getRecordClasses($other));
65	    }
