77	        ]);
78	        $product = Product::create(['name' => ['it' => 'Tavolino Kandy'], 'category_2_id' => $category2->id, 'product_type_id' => $productType->id]);
79	
80	        $table = Livewire::test(ListProducts::class)->instance()->getTable();
81	
82	        $this->assertSame([], $table->getRecordClasses($product));
83	    }
84	
85	    /**
86	     * L'highlighting da solo non basta se il record è su una pagina diversa
87	     * dalla prima: la riga evidenziata non è nemmeno nel DOM finché non si
88	     * pagina manualmente. `IsDigitalHubListPage::bootedIsDigitalHubListPage()`
89	     * salta alla pagina giusta calcolando la posizione del record nella
90	     * query ordinata/filtrata della tabella (10 per pagina di default).
91	     */
92	    public function test_landing_on_a_record_beyond_the_first_page_jumps_to_its_page(): void
93	    {
