95	        Filament::setCurrentPanel('admin');
96	
97	        $category1 = Category1::create(['name' => ['it' => 'Indoor']]);
98	        $category2 = Category2::create(['name' => ['it' => 'Collezione'], 'category_1_id' => $category1->id]);
99	        $productType = ProductType::create([
100	            'name' => ['it' => 'Tavolo'],
101	            'attribute_schema_class' => \App\Pim\Schemas\ProductAttributes::class,
102	        ]);
103	
104	        // 25 prodotti, 10 per pagina di default: il 21° (indice 20) è a pagina 3.
105	        $products = collect(range(1, 25))->map(fn (int $i) => Product::create([
106	            'name' => ['it' => "Prodotto {$i}"],
107	            'category_2_id' => $category2->id,
108	            'product_type_id' => $productType->id,
109	        ]));
